mapper.select:
select * from safety_spot_link_record_rule lr
where lr.device_id = #{deviceId}
  and lr.record_id = #{recordId}
order by lr.rule_sort asc

select count(*)
from safety_spot_check_device_info t

         LEFT JOIN safety_employee_message ce ON ce.emp_no IN (
             SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(t.check_emp_no, ',', numbers.n), ',', -1)
             FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
             UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9
             UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12
             ) numbers
             WHERE numbers.n <= (LENGTH(t.check_emp_no) - LENGTH(REPLACE(t.check_emp_no, ',', '')) + 1)
         )
         LEFT JOIN safety_employee_message pe ON pe.emp_no IN (
             SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(t.pro_tem_check_emp_no, ',', numbers.n), ',', -1)
             FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
             UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9
             UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12
             ) numbers
             WHERE numbers.n <= (LENGTH(t.pro_tem_check_emp_no) - LENGTH(REPLACE(t.pro_tem_check_emp_no, ',', '')) + 1)
         )

where t.id = #{deviceId}
  and (
          (ce.email like CONCAT(#{username}, '@', '%') and ce.status = 'NORMAL')
       or (pe.email like CONCAT(#{username}, '@', '%')

           and t.pro_tem_begin_date <= #{dat}

           and t.pro_tem_end_date >= #{dat}
           and pe.status = 'NORMAL')
  )

mapper.update:
update safety_spot_check_record t set

    t.reform_emp = #{user.empName}, t.reform_emp_no = #{user.empNo}, t.plan_reform_date = #{user.reformTime}


    t.is_reform = 1, t.reform_time = now()


    t.validate_status = 1, t.validate_time = now(), t.validate_emp = #{user.empName}, t.validate_emp_no = #{user.empNo}


    t.validate_status = 4, t.validate_time = now(), t.validate_emp = #{user.empName}, t.validate_emp_no = #{user.empNo}

where t.flow_id = #{flowId}

mapper.select:
SELECT DISTINCT p.* FROM safety_spot_check_process P ,safety_spot_check_record r WHERE p.flow_id = r.flow_id AND P.`status` = '20'
and p.node_flag = #{nodeFlag}
and R.`status` = #{status}
and R.plan_reform_date IS NULL
and P.reform_time < NOW()+1

mapper.update:
update safety_spot_check_result
set valid_result = #{validResult}

    ,valid_remark = #{validRemark}


    ,valid_name = #{user.empName}

where record_id =
      (select id from safety_spot_check_record where flow_id = #{flowId} limit 1)
order by reform_time desc
limit 1
